class _Path0Painter extends CustomPainter {
  const _Path0Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(200, 0);
    path.lineTo(200, 30);
    path.lineTo(0, 30);
    path.lineTo(0, 0);
    path.close();
    canvas.drawPath(path, Paint()..color = Color(0x1AFE4066));
    canvas.drawPath(
      path,
      Paint()
        ..color = Color(0x99FE4066)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
    );
  }

  @override
  bool shouldRepaint(_Path0Painter oldDelegate) => false;
}

class _Path1Painter extends CustomPainter {
  const _Path1Painter();

  @override
  void paint(Canvas canvas, Size size) {
    final path = Path();
    path.moveTo(0, 0);
    path.lineTo(94, 0);
    path.lineTo(94, 30);
    path.lineTo(0, 30);
    path.lineTo(0, 0);
    path.close();
    canvas.drawPath(path, Paint()..color = Color(0x1AFE4066));
    canvas.drawPath(
      path,
      Paint()
        ..color = Color(0x99FE4066)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
    );
  }

  @override
  bool shouldRepaint(_Path1Painter oldDelegate) => false;
}
